        var h = document.createElement('span');
        h.className = 'hint';
        h.textContent = (params.pageLayout !== 'continuous' && !params.gridEnabled && !metricsDirty && Number.isInteger(selectedM.pageIndex)
          ? '元の配置：' + layoutContextLabel({ first: selectedM.pageIndex, last: selectedM.pageIndex }) + ' · ' : '')
          + '←→↑↓ 微調整（⇧で大きく）・⌫ 初期化・esc 解除';
