        var el = selectedM.el;
        var id = params.activeOperator;
        var state = operatorState(selectedM, id);
        var base = manualValueAtDragStart(selectedM, id);
        if (id === 'stretch') {
          selectedM.manualX = Math.min(8, Math.max(0.25, base.x + dx));
          selectedM.manualY = Math.min(9, Math.max(0.25, base.y + dy));
        } else if (id === 'confuse') state.manual = Math.max(0, Math.min(1, base + dx + dy));
        else if (id === 'rotate') state.manual = (globalThis.TypeDeformerParameters?TypeDeformerParameters.normalize('rotateAngle',base + dx * 20,0,-720,720):Math.max(-720, Math.min(720, base + dx * 20)));
        else if (id === 'skew') state.manual = globalThis.TypeDeformerParameters ? {x:TypeDeformerParameters.normalize('skewX',base.x+dx*20,base.x),y:TypeDeformerParameters.normalize('skewY',base.y+dy*20,base.y)} : { x: Math.max(-85, Math.min(85, base.x + dx * 20)), y: Math.max(-85, Math.min(85, base.y + dy * 20)) };
        else if (id === 'baselineShift') state.manual = (globalThis.TypeDeformerParameters?TypeDeformerParameters.normalize('baselineShift',base + (params.vertical ? dx : dy),0,-12,12):Math.max(-12, Math.min(12, base + (params.vertical ? dx : dy))));
        else if (id === 'mirror') state.manual = { x: Math.max(-1, Math.min(1, base.x - dx)), y: Math.max(-1, Math.min(1, base.y - dy)) };
        else if (id === 'dataMosh') state.manual = { x: Math.max(-640, Math.min(640, base.x + dx * 20)), y: Math.max(-640, Math.min(640, base.y - dy * 20)) };
        else if (id === 'blobTrack') state.manual = { x: Math.max(-2000, Math.min(2000, base.x + dx * 20)), y: Math.max(-2000, Math.min(2000, base.y - dy * 20)) };
        else if (id === 'axisField' || id === 'counterspaceFlow' || id === 'concordanceField' || id === 'paragraphCurrent' || id === 'readingField' || id === 'gutterFugue' || id === 'caesuraField' || isSurfaceOperator(id)) state.manual = Math.max(0, Math.min(1, base + dx + dy));
        else state.manual = { x: Math.max(-120, Math.min(120, base.x + dx * 20)), y: Math.max(-120, Math.min(120, base.y - dy * 20)) };
