          if (bounds && sourceTargetSpanIndex(bounds, Number(m.el.dataset.sourceStart), Number(m.el.dataset.sourceEnd)) < 0) continue;
          var ch = m.el.dataset.sourceText || m.el.textContent;
          var cp = parseInt(m.el.dataset.cp, 10) || ch.codePointAt(0);
