      var surfaceMixerName = document.getElementById('surfaceMixerName');
      var surfaceTextColorInput = document.getElementById('pSurfaceTextColor');
      var surfaceEffectColorInput = document.getElementById('pSurfaceEffectColor');
      var surfaceEffectColorBInput = document.getElementById('pSurfaceEffectColorB');
      var surfaceEffectColorLabel = document.getElementById('surfaceEffectColorLabel');
      var surfaceSecondColorRow = document.getElementById('surfaceSecondColorRow');
      var surfaceSourceOpacityInput = document.getElementById('pSurfaceSourceOpacity');
      var surfaceSourceOpacityValue = document.getElementById('vSurfaceSourceOpacity');
      var surfaceSourcePresetButtons = document.querySelectorAll('[data-surface-source-opacity]');
      var surfaceOpacityInput = document.getElementById('pSurfaceOpacity');
      var surfaceOpacityValue = document.getElementById('vSurfaceOpacity');
      var surfaceOpacityPresetButtons = document.querySelectorAll('[data-surface-effect-opacity]');
      var surfaceBlendInput = document.getElementById('pSurfaceBlend');
      var surfaceOrderLabel = document.getElementById('surfaceOrderLabel');
      var btnSurfaceBack = document.getElementById('btnSurfaceBack');
      var btnSurfaceFront = document.getElementById('btnSurfaceFront');
      var mirrorXInput = document.getElementById('pMirrorX');
      var mirrorYInput = document.getElementById('pMirrorY');
      var controlPanel = document.querySelector('.panel');
      document.getElementById('effectiveParameterBlock').addEventListener('toggle', refreshEffectiveParameterInspector);
      var projectMenu = document.getElementById('projectMenu');
      var mobileProjectButton = document.getElementById('btnMobileProject');
      var pendingControlHistory = null;
      var operatorGuideCategory = document.getElementById('operatorGuideCategory');
      var operatorGuideSummary = document.getElementById('operatorGuideSummary');
      var operatorBrowser = document.getElementById('operatorBrowser');
      var operatorBrowserKicker = document.getElementById('operatorBrowserKicker');
