      function editWassersteinPartner(event) {
        if (event.isComposing) return;
        var input = document.getElementById('pWassersteinPartner'), value = input.value;
        var valid = TypeDeformerWassersteinLetters.validText(value);
        input.setAttribute('aria-invalid', String(!valid));
        document.getElementById('wassersteinPartnerStatus').textContent = valid ? '相手は1〜32文字。文字列全体では対象をまとめ、先頭の対象文字の書体・設定を使います。' : '1〜32文字を1行で指定してください。設定はまだ変更していません。';
        if (!valid || value === params.wassersteinPartner) return;
        pushHistory(); params.wassersteinPartner = value; applyAllOperatorVisuals(); markAutosaveDirty();
      }
      document.getElementById('pWassersteinPartner').addEventListener('input', editWassersteinPartner);
      document.getElementById('pWassersteinPartner').addEventListener('compositionend', editWassersteinPartner);
      document.getElementById('pWassersteinScope').addEventListener('change', function () {
        pushHistory(); params.wassersteinScope = this.value === 'text' ? 'text' : 'glyph'; applyAllOperatorVisuals(); markAutosaveDirty();
      });
      function editAnamorphicPartner(event) {
        if (event.isComposing) return;
        var input = document.getElementById('pAnamorphicPartner'), value = input.value;
        var valid = !!value.trim() && value.length <= 32 && renderEngine.toGraphemes(value).length === 1;
        input.setAttribute('aria-invalid', String(!valid));
        document.getElementById('anamorphicPartnerStatus').textContent = valid ? '共通の相手文字です。原文は変更しません。' : '相手は空白以外の一文字を指定してください。まだ設定は変更していません。';
        if (!valid || value === params.anamorphicPartner) return;
        params.anamorphicPartner = value; applyAllOperatorVisuals(); markAutosaveDirty();
      }
