      function displayedCompositionText() {
        var paragraphs = stage.querySelectorAll('p');
        var lines = [];
        for (var i = 0; i < paragraphs.length; i++) lines.push(paragraphs[i].textContent.replace(/\u00a0/g, ' '));
        return lines.join('\n');
      }

      var copyTextStatus = document.getElementById('copyTextStatus');
      var manualCopyOverlay = document.getElementById('manualCopyOverlay');
      var manualCopyTitle = document.getElementById('manualCopyTitle');
      var manualCopyLabel = document.getElementById('manualCopyLabel');
      var manualCopyValue = document.getElementById('manualCopyValue');
      var manualCopyStatus = document.getElementById('manualCopyStatus');
      var btnManualCopyClose = document.getElementById('btnManualCopyClose');
      var btnManualCopyRetry = document.getElementById('btnManualCopyRetry');
      var btnManualCopySelect = document.getElementById('btnManualCopySelect');
      var manualCopyReturnFocus = null;
      var manualCopyResultHandler = null;
      var manualCopySucceeded = false;

      function setCopyTextStatus(message, state) {
        copyTextStatus.textContent = message || '';
        copyTextStatus.hidden = !message;
        if (state) copyTextStatus.dataset.state = state;
        else copyTextStatus.removeAttribute('data-state');
      }

      function setManualCopyStatus(message, state) {
        manualCopyStatus.textContent = message || '';
        if (state) manualCopyStatus.dataset.state = state;
        else manualCopyStatus.removeAttribute('data-state');
      }

      function selectManualCopyValue() {
        manualCopyValue.focus({ preventScroll: true });
        manualCopyValue.setSelectionRange(0, manualCopyValue.value.length);
        setManualCopyStatus('全体を選択しました。長押し、または Ctrl / ⌘ + C でコピーできます。');
      }

      function openManualCopy(value, label, returnFocus, resultHandler) {
        manualCopyReturnFocus = returnFocus && returnFocus.isConnected ? returnFocus : document.activeElement;
        manualCopyResultHandler = typeof resultHandler === 'function' ? resultHandler : null;
        manualCopySucceeded = false;
        manualCopyTitle.textContent = 'Copy ' + label;
        manualCopyLabel.textContent = label;
        manualCopyValue.value = String(value == null ? '' : value);
        btnManualCopyRetry.disabled = false;
        setManualCopyStatus('クリップボードへ直接書き込めませんでした。テキスト全体を選択しています。', 'error');
        manualCopyOverlay.hidden = false;
        requestAnimationFrame(selectManualCopyValue);
      }

      function closeManualCopy() {
        if (manualCopyOverlay.hidden) return;
        manualCopyOverlay.hidden = true;
        var returnFocus = manualCopyReturnFocus;
        var resultHandler = manualCopyResultHandler;
        var succeeded = manualCopySucceeded;
        manualCopyReturnFocus = null;
        manualCopyResultHandler = null;
        manualCopySucceeded = false;
        manualCopyValue.value = '';
        if (resultHandler && !succeeded) resultHandler(false);
        if (returnFocus && returnFocus.isConnected && !returnFocus.disabled) {
          requestAnimationFrame(function () { returnFocus.focus({ preventScroll: true }); });
        }
      }

      function retryManualCopy() {
        var handler = manualCopyResultHandler;
        if (!navigator.clipboard || !navigator.clipboard.writeText) {
          selectManualCopyValue();
          setManualCopyStatus('このブラウザでは直接コピーできません。選択したテキストを長押ししてコピーしてください。', 'error');
          if (handler) handler(false);
          return;
        }
        btnManualCopyRetry.disabled = true;
        setManualCopyStatus('Copying…', 'working');
        navigator.clipboard.writeText(manualCopyValue.value).then(function () {
          btnManualCopyRetry.disabled = false;
          manualCopySucceeded = true;
          setManualCopyStatus('Copied to clipboard. Closeで元の操作へ戻れます。', 'done');
          if (handler) handler(true);
        }, function () {
          btnManualCopyRetry.disabled = false;
          selectManualCopyValue();
          setManualCopyStatus('直接コピーはまだ許可されていません。選択したテキストを長押ししてコピーしてください。', 'error');
          if (handler) handler(false);
        });
      }

      btnManualCopyClose.addEventListener('click', closeManualCopy);
      btnManualCopyRetry.addEventListener('click', retryManualCopy);
      btnManualCopySelect.addEventListener('click', selectManualCopyValue);
      manualCopyOverlay.addEventListener('click', function (event) {
        if (event.target === manualCopyOverlay) closeManualCopy();
      });
      document.addEventListener('keydown', function (event) {
        if (manualCopyOverlay.hidden) return;
        if (event.key === 'Escape') {
          closeManualCopy();
          event.preventDefault();
          event.stopImmediatePropagation();
          return;
        }
        if (event.key !== 'Tab') return;
        var focusable = [btnManualCopyClose, manualCopyValue, btnManualCopyRetry, btnManualCopySelect].filter(function (control) {
          return !control.disabled;
        });
        var current = focusable.indexOf(document.activeElement);
        if (event.shiftKey && current <= 0) {
          focusable[focusable.length - 1].focus({ preventScroll: true });
          event.preventDefault();
        } else if (!event.shiftKey && (current < 0 || current === focusable.length - 1)) {
          focusable[0].focus({ preventScroll: true });
          event.preventDefault();
        }
      }, true);

      function copyPlainTextValue(value, button, label) {
        var originalLabel = button.dataset.copyDefaultLabel || button.textContent;
        button.dataset.copyDefaultLabel = originalLabel;
        var flashButton = function (message) {
          button.textContent = message;
          setTimeout(function () { button.textContent = originalLabel; }, 1600);
        };
        var manualResult = function (ok) {
          if (ok) {
            flashButton('Copied!');
            setCopyTextStatus(label + ' copied to clipboard', 'done');
          } else {
            setCopyTextStatus(label + ' needs manual copy · 全体を選択済み', 'error');
          }
        };
        var offerManualCopy = function () {
          flashButton('Copy manually');
          setCopyTextStatus(label + ' needs manual copy · 全体を選択済み', 'error');
          openManualCopy(value, label, button, manualResult);
        };
        setCopyTextStatus('Copying ' + label + '…', 'working');
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(value).then(function () {
            flashButton('Copied!');
            setCopyTextStatus(label + ' copied to clipboard', 'done');
          }, offerManualCopy);
        } else {
          offerManualCopy();
        }
      }

      var btnCopySourceText = document.getElementById('btnCopySourceText');
      var btnCopyDerivedText = document.getElementById('btnCopyDerivedText');
      btnCopySourceText.addEventListener('click', function () { copyPlainTextValue(textInput.value, btnCopySourceText, 'Source text / 原文'); });
      btnCopyDerivedText.addEventListener('click', function () { copyPlainTextValue(displayedCompositionText(), btnCopyDerivedText, 'Display text / 表示'); });

      // Ordinary copy from the artwork always yields immutable source text.
      // The explicit Copy display action above is the only path that exports
      // derived Confuse characters as plain text.
      document.addEventListener('copy', function (e) {
        var selection = window.getSelection && window.getSelection();
        if (!selection || !selection.rangeCount || !e.clipboardData) return;
        var range = selection.getRangeAt(0);
        try { if (!range.intersectsNode(stage)) return; }
        catch (unsupportedRange) { return; }
        var container = document.createElement('div');
        container.appendChild(range.cloneContents());
        var copiedGlyphs = container.querySelectorAll('.c');
        for (var i = 0; i < copiedGlyphs.length; i++) {
          if (copiedGlyphs[i].dataset.sourceText) copiedGlyphs[i].textContent = copiedGlyphs[i].dataset.sourceText;
        }
        var paragraphs = container.querySelectorAll('p');
        var lines = [];
        if (paragraphs.length) {
          for (var p = 0; p < paragraphs.length; p++) lines.push(paragraphs[p].textContent.replace(/\u00a0/g, ' '));
        } else lines.push(container.textContent.replace(/\u00a0/g, ' '));
        e.preventDefault();
        e.clipboardData.setData('text/plain', lines.join('\n'));
      });

