      function populateCompositionPresets() {
        var select = document.getElementById('pCompositionPreset');
        if (!select || select.dataset.engine === compositionInspector) return;
        select.dataset.engine = compositionInspector;
        select.innerHTML = '<option value="">Scene preset…</option>';
        var presets = COMPOSITION_PRESETS[compositionInspector] || {};
        Object.keys(presets).forEach(function (key) {
          var option = document.createElement('option');
          option.value = key;
          option.textContent = presets[key].label;
          select.appendChild(option);
        });
        document.getElementById('btnCompositionPresetApply').disabled = true;
      }
      document.getElementById('pCompositionPreset').addEventListener('change', function (e) {
        document.getElementById('btnCompositionPresetApply').disabled = !e.target.value;
      });
      document.getElementById('btnCompositionPresetApply').addEventListener('click', function () {
        var select = document.getElementById('pCompositionPreset');
        var preset = COMPOSITION_PRESETS[compositionInspector] && COMPOSITION_PRESETS[compositionInspector][select.value];
        if (!preset) return;
        pushHistory();
        var preservedVesselImage = compositionInspector === 'glyphVessel' ? {
          imageData: compositionState.glyphVessel.imageData,
          imageWidth: compositionState.glyphVessel.imageWidth,
          imageHeight: compositionState.glyphVessel.imageHeight,
          imageName: compositionState.glyphVessel.imageName
        } : null;
        var next = JSON.parse(JSON.stringify(COMPOSITION_DEFAULTS[compositionInspector]));
        Object.keys(preset.state).forEach(function (key) { next[key] = preset.state[key]; });
        if (preservedVesselImage && preservedVesselImage.imageData) {
          next.imageData = preservedVesselImage.imageData;
          next.imageWidth = preservedVesselImage.imageWidth;
          next.imageHeight = preservedVesselImage.imageHeight;
          next.imageName = preservedVesselImage.imageName;
        }
        compositionState[compositionInspector] = next;
        markAutosaveDirty();
        syncCompositionUI();
      });
      document.getElementById('pSignalRouterPreset').addEventListener('change', function (e) {
        document.getElementById('btnSignalRouterPresetApply').disabled = !e.target.value;
      });
      document.getElementById('btnSignalRouterPresetApply').addEventListener('click', function () {
        var select = document.getElementById('pSignalRouterPreset');
        var preset = SIGNAL_ROUTER_PRESETS[select.value];
        if (!preset) return;
        pushHistory();
        var next = JSON.parse(JSON.stringify(COMPOSITION_DEFAULTS.signalRouter));
        for (var slotIndex = 0; slotIndex < next.length; slotIndex++) {
          var overrides = preset[slotIndex] || {};
          Object.keys(overrides).forEach(function (key) { next[slotIndex][key] = overrides[key]; });
        }
        compositionState.signalRouter = next;
        select.value = '';
        document.getElementById('btnSignalRouterPresetApply').disabled = true;
        markAutosaveDirty();
        syncCompositionUI();
      });

      for (var compositionControlIndex = 0; compositionControlIndex < COMPOSITION_RANGE_CONTROLS.length; compositionControlIndex++) {
        (function (spec) {
          var input = document.getElementById(spec[0]);
          if (!input) return;
          // The shared control transaction owns pointer, keyboard and direct
          // number edits, so Compose also records exactly one Undo per edit.
          input.addEventListener('input', function () {
            var displayValue = Number(input.value);
            setCompositionValue(spec[2], spec[3], compositionControlStateValue(displayValue, spec[6]));
            var output = spec[1] ? document.getElementById(spec[1]) : null;
            if (output) output.textContent = displayValue.toFixed(spec[4]) + (spec[5] || '');
            markAutosaveDirty();
            scheduleCompositionDraw();
            scheduleEffectStatusUpdate();
          });
        })(COMPOSITION_RANGE_CONTROLS[compositionControlIndex]);
      }

