        document.getElementById('exportCustomSizeRow').hidden = document.getElementById('pExportLongEdge').value !== 'custom';
        document.getElementById('exportCustomSizeRow').style.display = document.getElementById('pExportLongEdge').value === 'custom' ? '' : 'none';
        document.getElementById('pScale').disabled = tightImageExport() && params.exportLongEdge > 0;
