      var modeButtons = {
        flow: document.getElementById('btnModeFlow'),
        lock: document.getElementById('btnModeLock'),
        edit: document.getElementById('btnModeEdit'),
        grid: document.getElementById('btnModeGrid')
      };
      function updateApplicationModeHint() {
        var hint = document.getElementById('applicationModeHint');
        if (!hint || !OPERATOR_DEFS[params.activeOperator]) return;
        var operatorLabel = OPERATOR_DEFS[params.activeOperator].label;
        if (params.mode === 'edit') {
          hint.textContent = 'Edit：Doneで閉じ、文字をタップして' + operatorLabel + 'を個別調整。';
        } else if (params.mode === 'grid') {
          hint.textContent = 'Arrange：Doneで閉じ、Gridセル間で文字を移動。';
        } else if (params.mode === 'lock') {
          hint.textContent = 'Freeze pick：Doneで閉じ、文字をタップして固定／解除。';
        } else {
          hint.textContent = 'Lens：Doneで閉じ、文字をなぞって' + operatorLabel + 'を塗る。Quick applyなら選択対象へ一括適用。';
        }
      }
      function updateArrangeAvailability() {
        var disabled = compositionState.enabled;
        var reason = compositionState.enabled
          ? 'Composition owns the visible layout. Remove it to arrange the source grid.'
          : (!params.gridEnabled ? 'Arrangeを選ぶとGrid設定を開きます。' : 'Grid layout is ready. Arrange moves glyphs between cells.');
        Array.prototype.forEach.call(document.querySelectorAll('#btnModeGrid, [data-mobile-mode="grid"]'), function (button) {
          button.disabled = disabled;
          button.setAttribute('aria-disabled', String(disabled));
          button.textContent = !disabled && !params.gridEnabled ? 'Arrange →' : 'Arrange';
          button.title = disabled ? reason : (!params.gridEnabled ? 'Arrange: open Grid settings' : 'Arrange: move glyphs between grid cells');
        });
        var gridLink = document.getElementById('btnOpenGridSettings');
        if (gridLink) gridLink.hidden = true;
        updateApplicationModeHint();
      }
      function setMode(mode) {
        if (mode === 'grid' && !params.gridEnabled) {
          if (compositionState.enabled) return;
          var gridSettingsLink = document.getElementById('btnOpenGridSettings');
          if (gridSettingsLink) gridSettingsLink.click();
          return;
        }
        if (mode === 'grid' && compositionState.enabled && params.mode !== 'grid') return;
        if (canvasView.active) setCanvasViewActive(false);
        params.mode = mode;
        markAutosaveDirty();
        controlPanel.dataset.mode = mode;
        // A hover latch from Flow must never survive a mode round-trip;
        // otherwise the first sweep after returning to Flow can be ignored.
        for (var i = 0; i < metrics.length; i++) {
          for (var operatorId in metrics[i].operatorStates) metrics[i].operatorStates[operatorId].hovered = false;
        }
        for (var k in modeButtons) modeButtons[k].setAttribute('aria-pressed', String(k === mode));
        stage.classList.toggle('lock-mode', mode === 'lock');
        stage.classList.toggle('edit-mode', mode === 'edit');
        stage.classList.toggle('grid-mode', mode === 'grid');
        clearEditSelection();
        updateArrangeAvailability();
        updateContextUI();
        updateApplicationModeHint();
      }
      modeButtons.flow.addEventListener('click', function () { setMode('flow'); });
      modeButtons.lock.addEventListener('click', function () { setMode('lock'); });
      modeButtons.edit.addEventListener('click', function () { setMode('edit'); });
      modeButtons.grid.addEventListener('click', function () { setMode('grid'); });
      var btnXray = document.getElementById('btnXray');
