        document.getElementById('pExportLongEdge').value = [0, 2048, 4096, 8192].includes(params.exportLongEdge) ? String(params.exportLongEdge) : 'custom';
        document.getElementById('pExportCustomSize').value = params.exportLongEdge || 8192;
        document.getElementById('pExportPadding').value = params.exportPadding;
        document.getElementById('vExportPadding').textContent = params.exportPadding + '%';
        document.getElementById('pExportDpi').value = String(params.exportDpi);
        document.getElementById('pExportName').value = params.exportName;
